using System; using System.Text; using System.Collections.Generic; using System.Runtime.InteropServices;
public class Q { public delegate bool CB(IntPtr h, IntPtr l);
 [DllImport("user32.dll")] public static extern bool EnumWindows(CB c, IntPtr l);
 [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint p);
 [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
 [DllImport("user32.dll")] public static extern bool IsWindowEnabled(IntPtr h);
 [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetClassName(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr h, StringBuilder s, int n);
 [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out int[] r);
 [DllImport("user32.dll")] public static extern int GetWindowLong(IntPtr h, int i);
 [DllImport("user32.dll")] public static extern bool RedrawWindow(IntPtr h, IntPtr a, IntPtr b, uint f);
 public static List<string> Dump(uint pid) { var r = new List<string>(); EnumWindows((h, l) => { uint p; GetWindowThreadProcessId(h, out p); if (p == pid) { var c = new StringBuilder(128); var t = new StringBuilder(128); GetClassName(h, c, 128); GetWindowText(h, t, 128); r.Add(h + " cls=" + c + " title=" + t + " vis=" + IsWindowVisible(h) + " en=" + IsWindowEnabled(h) + " st=" + GetWindowLong(h, -16).ToString("X") + " ex=" + GetWindowLong(h, -20).ToString("X")); RedrawWindow(h, IntPtr.Zero, IntPtr.Zero, 0x185); } return true; }, IntPtr.Zero); return r; } }
'@; $p=Get-Process KeePassXC | select -First 1; [Q]::Dump([uint32]$p.Id) | % { "W: $_" }; "mods: " + (($p.Modules | select -First 60 | % { $_.ModuleName }) -join ','); Start-Sleep 2; Add-Type -AssemblyName System.Windows.Forms; $b=[System.Windows.Forms.SystemInformation]::VirtualScreen; $bmp=New-Object System.Drawing.Bitmap $b.Width,$b.Height; [System.Drawing.Graphics]::FromImage($bmp).CopyFromScreen($b.Location,[System.Drawing.Point]::Empty,$b.Size); $bmp.Save('out/kp_after.png')
